#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(message, code = 2) {
    super(message)
    this.code = code
  }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const costs = new Map()
  const depLines = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (costs.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      costs.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      depLines.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  const deps = new Map([...costs.keys()].map((k) => [k, new Set()]))
  for (const w of depLines) {
    for (const name of w) if (!costs.has(name)) throw new Fail(`error: unknown task ${name}`)
    for (const d of w.slice(1)) deps.get(w[0]).add(d)
  }
  const names = [...costs.keys()].sort(cmp)
  const dl = new Map(names.map((k) => [k, [...deps.get(k)].sort(cmp)]))
  return { names, costs, deps: dl }
}

function findCycle({ names, deps }) {
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of deps.get(u)) {
      const s = state.get(v)
      if (s === 1) return [...stack.slice(stack.indexOf(v)), v]
      if (!s) {
        const c = visit(v)
        if (c) return c
      }
    }
    stack.pop()
    state.set(u, 2)
    return null
  }
  for (const n of names) {
    if (!state.get(n)) {
      const c = visit(n)
      if (c) return c
    }
  }
  return null
}

function timings(g) {
  const info = new Map()
  const calc = (u) => {
    if (info.has(u)) return info.get(u)
    let start = 0n
    let depth = 0
    for (const d of g.deps.get(u)) {
      const x = calc(d)
      if (x.finish > start) start = x.finish
      if (x.depth + 1 > depth) depth = x.depth + 1
    }
    const r = { start, finish: start + g.costs.get(u), depth }
    info.set(u, r)
    return r
  }
  let total = 0n
  for (const n of g.names) {
    const r = calc(n)
    if (r.finish > total) total = r.finish
  }
  return { info, total }
}

function pack(g, workers) {
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    return null
  }
  // dependents map
  const rev = new Map(g.names.map((n) => [n, []]))
  for (const n of g.names) for (const d of g.deps.get(n)) rev.get(d).push(n)
  const calc = (u) => {
    const c = pr(u)
    if (c !== null) return c
    let best = 0n
    for (const v of rev.get(u)) {
      const x = calc(v)
      if (x > best) best = x
    }
    const r = best + g.costs.get(u)
    prio.set(u, r)
    return r
  }
  for (const n of g.names) calc(n)
  const order = [...g.names].sort((a, b) => (prio.get(a) === prio.get(b) ? cmp(a, b) : prio.get(a) > prio.get(b) ? -1 : 1))
  const finish = new Map()
  const freeAt = Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  let t = 0n
  let makespan = 0n
  while (finish.size < g.names.length) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      const task = order.find(
        (n) => !finish.has(n) && g.deps.get(n).every((d) => finish.has(d) && finish.get(d) <= t),
      )
      if (task === undefined) break
      const f = t + g.costs.get(task)
      finish.set(task, f)
      freeAt[w] = f
      ran[w].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (finish.size === g.names.length) break
    t = freeAt.filter((f) => f > t).reduce((a, b) => (a < b ? a : b))
  }
  return ran.map((r, i) => `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`).join('') + `makespan ${makespan}\n`
}

function main() {
  const args = process.argv.slice(2)
  const cmd = args[0]
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  let workers = 0
  if ((cmd === 'waves' || cmd === 'explain') && args.length === 1) {
    // ok
  } else if (cmd === 'pack' && args.length === 2) {
    if (!/^[1-9][0-9]*$/.test(args[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(args[1])
  } else {
    throw new Fail(usage)
  }
  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {
    text = ''
  }
  const g = parse(text)
  const cyc = findCycle(g)
  if (cyc) throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
  if (cmd === 'pack') return pack(g, workers)
  const { info, total } = timings(g)
  let out = ''
  if (cmd === 'waves') {
    const waves = []
    for (const n of g.names) (waves[info.get(n).depth] ||= []).push(n)
    waves.forEach((w, k) => (out += `wave ${k}: ${w.join(' ')}\n`))
  } else {
    for (const n of g.names) {
      const r = info.get(n)
      out += `${n} start=${r.start} finish=${r.finish} depth=${r.depth}\n`
    }
  }
  return out + `total ${total}\n`
}

try {
  process.stdout.write(main())
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(e.code)
}
